#ifndef CSP_RS485_PROFILE_H
#define CSP_RS485_PROFILE_H

#define CSP_RS485_BAUD_RATE 921600U
#define CSP_RS485_BITS_PER_WIRE_BYTE 10U

#define CSP_RS485_DMA_BUFFER_SIZE 4096U
#define CSP_RS485_DMA_MAX_EVENT_BYTES 2048U
#define CSP_RS485_STREAM_BUFFER_SIZE 8192U

#define CSP_RS485_CSP_BUFFER_DATA_SIZE 300U
#define CSP_RS485_CSP_CRC_SIZE 4U
#define CSP_RS485_CSP_HEADER_SIZE 4U
#define CSP_RS485_INTERFACE_MTU \
    (CSP_RS485_CSP_BUFFER_DATA_SIZE - CSP_RS485_CSP_CRC_SIZE)
#define CSP_RS485_TX_RAW_MAX \
    (CSP_RS485_CSP_HEADER_SIZE + CSP_RS485_CSP_BUFFER_DATA_SIZE)
#define CSP_RS485_TX_FRAME_MAX (3U + (2U * CSP_RS485_TX_RAW_MAX))

#define CSP_RS485_IRQ_PRIORITY 5U

_Static_assert(CSP_RS485_INTERFACE_MTU == 296U, "Unexpected CSP RS485 MTU");
_Static_assert(CSP_RS485_TX_RAW_MAX == 304U, "Unexpected raw frame maximum");
_Static_assert(CSP_RS485_TX_FRAME_MAX == 611U, "Unexpected KISS frame maximum");
_Static_assert(
    CSP_RS485_DMA_MAX_EVENT_BYTES * 2U == CSP_RS485_DMA_BUFFER_SIZE,
    "DMA event bound must be one half-buffer");

#endif
